class Solution:
    def numIslands(self, grid: list[list[str]]) -&gt; int:
        if not grid:
            return 0
        rows, cols = len(grid), len(grid[0])
        count = 0

        def bfs(r: int, c: int) -&gt; None:
            queue = deque([(r, c)])
